<script type="text/javascript">
  teeinblue = {
    gallerySelector: 'product-gallery .product-gallery__image-list',
    cartContainerSelectors: ['.cart-drawer__items'],
    cartItemWrapperSelectors: ['.cart-drawer__items .line-item'],
    formSelector: '[data-block-id="buy_buttons"] product-form form',
    addToCartWrapperSelector: '[data-block-id="buy_buttons"] product-form form buy-buttons',
    atcSubmitSelector: '[data-block-id="buy_buttons"] product-form form buy-buttons button[type="submit"]',
    formCssSelector: '[data-block-id="buy_buttons"] product-form form .v-stack.gap-4',
    formEmbedMethod: 'css-selector',
    formEmbedType: 'before',
    // [CÁCH 1]: Bắn event cart:refresh trong callback onItemAdded
    onItemAdded: function(item) {
      document.documentElement.dispatchEvent(new CustomEvent('cart:refresh', { bubbles: true }));
      const cartDrawer = document.querySelector('cart-drawer');
      if (cartDrawer && typeof cartDrawer.show === 'function') {
        cartDrawer.show();
      }
    }
  };
</script>
<script type="text/javascript">
// [CÁCH 2]: Lắng nghe sự kiện teeinblue-event-after-cart-added và fetch /cart.js cập nhật badge header
document.addEventListener('teeinblue-event-after-cart-added', function() {
  fetch('/cart.js')
    .then(res => res.json())
    .then(data => {
      var cartCount = document.querySelectorAll('.header__cart-count cart-count, .cart-count');
      if (cartCount.length) {
        cartCount.forEach(function(cart) {
          cart.style.opacity = '1';
          cart.innerText = data.item_count;
        });
      }
    });
});
</script>

